CREATE TYPE "Role" AS ENUM ('CUSTOMER','ADMIN');
ALTER TABLE "Customer" ADD COLUMN role "Role" NOT NULL DEFAULT 'CUSTOMER';
CREATE TABLE "Supplier" (id SERIAL PRIMARY KEY, name TEXT NOT NULL, contact TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, "deliveryDays" INT NOT NULL CHECK ("deliveryDays">=0));
CREATE TABLE "Product" (id SERIAL PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', tag TEXT NOT NULL DEFAULT '', "pricePaise" INT NOT NULL CHECK ("pricePaise">0), image TEXT NOT NULL DEFAULT '', photo BYTEA, active BOOLEAN NOT NULL DEFAULT true, "supplierId" INT REFERENCES "Supplier"(id), "costPaise" INT CHECK ("costPaise">=0));
CREATE TABLE "Variant" (id SERIAL PRIMARY KEY, "productId" INT NOT NULL REFERENCES "Product"(id), size TEXT NOT NULL, color TEXT NOT NULL, stock INT NOT NULL DEFAULT 0 CHECK(stock>=0), UNIQUE("productId",size,color));
CREATE TABLE "Audit" (id SERIAL PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, detail TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Audit_target_id_idx" ON "Audit"(target,id);
ALTER TABLE "Order" ADD COLUMN tracking TEXT, ADD COLUMN "inventoryHold" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "paidAt" TIMESTAMP(3);
ALTER TABLE "OrderItem" ADD COLUMN "variantId" INT REFERENCES "Variant"(id), ADD COLUMN allocated BOOLEAN NOT NULL DEFAULT false, ADD COLUMN category TEXT, ADD COLUMN "costPaise" INT, ADD COLUMN "supplierId" INT REFERENCES "Supplier"(id), ADD COLUMN "supplierStatus" TEXT NOT NULL DEFAULT 'Awaiting', ADD COLUMN "supplierTracking" TEXT;
