SELECT setval(pg_get_serial_sequence('"Product"', 'id'),(SELECT MAX(id) FROM "Product"));
INSERT INTO "Variant" ("productId",size,color) SELECT id,'Standard','Original' FROM "Product" ORDER BY id;
UPDATE "OrderItem" i SET category=p.category FROM "Product" p WHERE i."productId"=p.id::text;
